/* Real products for categories that previously had no items.
   Scraped from applegadgetsbd.com listings (names, prices, discounts & product photos)
   so every category page now shows genuine products with images. */
import type { P } from "./catalog";
import { bdCategories, BD_PARENT_MAP } from "./bdCatalog";

export interface ExtraCategory {
  slug: string;
  title: string;
  tagline: string;
  /** full-width banner image (1500×323) exactly like the real listing page */
  banner?: string;
  brands: string[];
  items: P[];
}

let uid = 10000;
const p = (name: string, slug: string, price: number, img: string, brand: string, oldPrice?: number): P => ({
  id: uid++,
  name,
  slug,
  price,
  img,
  brand,
  ...(oldPrice && oldPrice > price ? { oldPrice } : {}),
});

