  "gadgets-accessories": ["chargers", "cables", "power-bank", "wireless-charger", "multiplugs", "action-camera"],
  "accessories": ["chargers", "cables", "power-bank", "wireless-charger", "multiplugs"],
  "chargers": ["chargers"],
